"""MTG's sound effects: soft, warm and suspenseful, all generated by code (no recordings, no licences, no copyright
claims). Shared by every video: they go to public/sfx/.

MTG's rule (7 November 2026): "some sound effects are too loud and too sharp ... I just want them to be soft,
interesting, pique interest". So every effect here has a gentle attack (no clicks), a warm tone (nothing piercing
above 6 kHz), a little room reverb, and the same moderate loudness. `check` measures that and fails on anything harsh.

Usage:
  python3 scripts/make_sound.py sfx      # build the palette into public/sfx/ (mp3) and check it
  python3 scripts/make_sound.py check    # measure every file in public/sfx/ against the soft rules

The palette (what each one is for):
  air        soft breath of air: scene changes, things sliding in
  swell      slow anticipation rise (about 2.5 s) that ends softly: just before a reveal
  tension    low, slow double pulse with a dark pad: questions, guesses, "here's the part most people miss"
  reveal     warm chord that blooms: the big number or the big idea lands
  drop       deep, soft sub drop: a serious turn ("less than one percent", "abandoned")
  glow       gentle sparkle pad, low passed: brand moments (MTG, MTG TRIBE)
  chime      soft bell: a question or a call to comment
  pluck1-5   soft marimba notes (G4 A4 C5 D5 E5): cards appearing; rising notes for building up, falling for losing
  tick       muted wooden tick: counting
  count      soft ticks that speed up (1.6 s): numbers climbing
  clock      slow, soft clock (4 s): waiting, time passing
  thud       soft low knock: a word or a stamp landing
  coin       mellow coin: money, dollar and rand
  paper      soft paper rustle: banknotes, posters
  shutter    low rolling rumble: a shop closing
  coinrain   a gentle cascade of coins landing: money piling up (video 01)
  whirr      clock hands spinning fast, softly: time racing (video 01)
  flutter    banknotes fluttering into place: posters, printing money (video 01)
  rise       soft low rumble that grows: something rising out of the floor (video 01's map)
  melt       a slow gliding fall in pitch: value melting away (video 01's pay bars)
  sink       a slow, low bubbling fall: something sinking into the sea (video 02's stone)
  link       a soft, muted clink: a block joining a chain (video 02's blockchain)
  key        two soft key clinks and a small jingle: a key appears or is copied (video 03)
  door       a soft, slow swing of air with a low wooden knock: a door opening quietly (video 03)

Every video gets effects that fit ITS story (MTG, 7 November 2026: "do not just use one and the same sound effects,
even if they do not fit"). When a moment needs a sound the palette does not have, add a new soft one here (with the
video it was made for), run `sfx`, and keep `check` at "all soft".
"""
import argparse
import glob
import os
import subprocess
import sys
import wave

import numpy as np

SR = 48000
HERE = os.path.dirname(os.path.abspath(__file__))
SFX_DIR = os.path.normpath(os.path.join(HERE, '..', 'public', 'sfx'))
RNG = np.random.default_rng(7)

# The soft rules (measured by `check`)
MAX_CENTROID_HZ = 2000  # brightness: the energy's centre of gravity stays warm
MAX_HF_PERCENT = 2.0  # energy above 6 kHz (hiss, sizzle, ear-piercing clicks)
MIN_ATTACK_MS = 4.0  # 10% to 90% rise time of the envelope: no instant clicks
TARGET_RMS_DB = -24.0  # every effect at the same moderate level (active part)
MAX_PEAK_DB = -3.0


def t(sec):
    return np.arange(int(sec * SR)) / SR


def lowpass(x, hz):
    spec = np.fft.rfft(x)
    f = np.fft.rfftfreq(len(x), 1 / SR)
    spec *= 1 / np.sqrt(1 + (f / hz) ** 8)  # steep, smooth roll-off
    return np.fft.irfft(spec, len(x))


def band(x, lo, hi):
    spec = np.fft.rfft(x)
    f = np.fft.rfftfreq(len(x), 1 / SR)
    spec *= (1 / np.sqrt(1 + (lo / np.maximum(f, 1)) ** 4)) * (1 / np.sqrt(1 + (f / hi) ** 8))
    return np.fft.irfft(spec, len(x))


def noise(sec):
    return RNG.standard_normal(int(sec * SR))


def env(n, attack, release, hold=0.0, curve=2.0):
    """Smooth envelope in seconds: raised-cosine attack, optional hold, exponential-ish release."""
    a = int(attack * SR)
    h = int(hold * SR)
    out = np.zeros(n)
    if a:
        out[:a] = 0.5 - 0.5 * np.cos(np.pi * np.arange(a) / a)
    out[a:a + h] = 1
    r = n - a - h
    if r > 0:
        out[a + h:] = np.exp(-curve * 3 * np.arange(r) / max(1, int(release * SR)))
    return out


def reverb(x, wet=0.25, seconds=1.2, tone=2500):
    """A small warm room: decaying low-passed noise as the impulse response, different per channel (width)."""
    tail = int(seconds * SR)
    out = []
    for ch in range(2):
        ir = np.random.default_rng(11 + ch).standard_normal(tail) * np.exp(-np.arange(tail) / (0.28 * SR))
        ir = lowpass(ir, tone)
        ir /= np.sqrt(np.sum(ir ** 2))
        y = np.convolve(np.concatenate([x, np.zeros(tail)]), ir)[:len(x) + tail]
        dry = np.concatenate([x, np.zeros(tail)])
        out.append(dry * (1 - wet) + y * wet * 1.4)
    return np.stack(out, axis=1)


def sine(freq, sec, phase=0.0):
    tt = t(sec)
    if callable(freq):
        ph = 2 * np.pi * np.cumsum(freq(tt)) / SR
        return np.sin(ph + phase)
    return np.sin(2 * np.pi * freq * tt + phase)


# The palette
def air():
    n = noise(0.9)
    sweep = np.linspace(0, 1, len(n))
    x = band(n, 250, 1800) * (0.6 + 0.4 * np.sin(np.pi * sweep))
    return x * env(len(x), 0.35, 0.45, curve=1.2)


def swell():
    d = 2.6
    tt = t(d)
    rise = (tt / d) ** 1.6
    pad = sum(sine(lambda u, f=f: f * (1 + 0.5 * (u / d) ** 1.6), d) for f in (220, 220.8, 330))  # audible on phones
    n = noise(d)
    hiss = np.zeros_like(n)
    for k in range(8):  # filter opens as it rises
        seg = slice(k * len(n) // 8, (k + 1) * len(n) // 8)
        hiss[seg] = band(n, 200, 500 + 220 * k)[seg]
    x = pad * 0.5 * rise + hiss * 0.5 * rise
    fade = np.ones_like(x)
    fade[-int(0.25 * SR):] = np.linspace(1, 0, int(0.25 * SR)) ** 2
    return x * fade * env(len(x), 0.6, d, hold=d)


def tension():
    d = 2.6
    x = np.zeros(int(d * SR))
    for at in (0.0, 0.32, 1.3, 1.62):
        # low pulse plus soft upper harmonics, so a phone speaker (which cannot play deep bass) still carries it
        fr = lambda u: 52 + 20 * np.exp(-u * 18)
        b = sum(sine(lambda u, m=m: m * fr(u), 0.6) * a for m, a in ((1, 1), (2, 0.55), (3, 0.35), (4, 0.2)))
        b *= env(int(0.6 * SR), 0.024, 0.25)
        i = int(at * SR)
        x[i:i + len(b)] += b * (1.0 if at in (0.0, 1.3) else 0.6)
    pad = (sine(293.7, d) + 0.6 * sine(349.2, d) + 0.4 * sine(440, d)) * env(int(d * SR), 0.8, 1.2, hold=0.8) * 0.16
    return lowpass(x + pad, 1200)


def reveal():
    d = 2.6
    notes = (261.6, 329.6, 392.0, 587.3)  # C E G D: warm, open
    x = sum(sine(f, d) * a for f, a in zip(notes, (1, 0.7, 0.6, 0.35)))
    x += 0.25 * sum(sine(f * 2, d) for f in notes[:2])
    return lowpass(x, 1800) * env(len(x), 0.06, 1.4, curve=1.0)


def drop():
    d = 1.6
    fr = lambda u: 30 + 90 * np.exp(-u * 3.5)
    x = sum(sine(lambda u, m=m: m * fr(u), d) * a for m, a in ((1, 1), (2, 0.6), (3, 0.4), (4, 0.25)))
    x *= env(int(d * SR), 0.02, 0.9)
    body = band(noise(d), 120, 600) * env(int(d * SR), 0.03, 0.25) * 0.3
    return lowpass(x + body, 900)


def glow():
    d = 2.4
    x = np.zeros(int(d * SR))
    for k, f in enumerate((784, 988, 1175, 1568, 1319)):  # soft sparkle notes, staggered
        s = sine(f, d - k * 0.12) * env(int((d - k * 0.12) * SR), 0.05, 0.9)
        i = int(k * 0.12 * SR)
        x[i:i + len(s)] += s * (0.9 - k * 0.12)
    x *= 0.75 + 0.25 * sine(5.5, d)  # gentle shimmer
    return lowpass(x, 1900)


def chime():
    d = 2.2
    f0 = 659.3
    x = sum(sine(f0 * r, d) * a * np.exp(-t(d) * k) for r, a, k in ((1, 1, 1.6), (2.0, 0.35, 2.4), (2.76, 0.18, 3.5)))
    return lowpass(x, 2200) * env(len(x), 0.015, d, hold=0.0, curve=0.25)


def pluck(f):
    def make():
        d = 0.9
        tt = t(d)
        x = (np.sin(2 * np.pi * f * tt) + 0.25 * np.sin(2 * np.pi * 4 * f * tt) * np.exp(-tt * 18)
             + 0.12 * np.sin(2 * np.pi * 2 * f * tt))
        return lowpass(x * env(len(tt), 0.014, 0.35, curve=1.0), 2400)
    return make


def tick():
    d = 0.16
    x = band(noise(d), 500, 1600) * env(int(d * SR), 0.009, 0.03)
    x += sine(880, d) * env(int(d * SR), 0.009, 0.04) * 0.3
    return lowpass(x, 2000)


def count():
    d = 1.7
    x = np.zeros(int(d * SR))
    times, at, gap = [], 0.0, 0.16
    while at < 1.5:
        times.append(at)
        at += gap
        gap = max(0.05, gap * 0.85)
    for k, at in enumerate(times):
        tk = band(noise(0.08), 500, 1500) * env(int(0.08 * SR), 0.004, 0.02)
        tk += sine(700 + 25 * k, 0.08) * env(int(0.08 * SR), 0.004, 0.03) * 0.35
        i = int(at * SR)
        x[i:i + len(tk)] += tk * (0.6 + 0.4 * k / len(times))
    return lowpass(x, 2000)


def clock():
    d = 4.0
    x = np.zeros(int(d * SR))
    for k in range(8):
        f = 900 if k % 2 == 0 else 760  # tick, tock
        tk = band(noise(0.1), 400, 1400) * env(int(0.1 * SR), 0.016, 0.03) + sine(f, 0.1) * env(int(0.1 * SR), 0.016, 0.04) * 0.3
        i = int(k * 0.5 * SR)
        x[i:i + len(tk)] += tk
    return lowpass(x, 1800)


def thud():
    d = 0.8
    fr = lambda u: 55 + 60 * np.exp(-u * 25)
    x = sum(sine(lambda u, m=m: m * fr(u), d) * a for m, a in ((1, 1), (2, 0.6), (3, 0.35))) * env(int(d * SR), 0.016, 0.3)
    x += band(noise(d), 120, 700) * env(int(d * SR), 0.012, 0.06) * 0.35
    return lowpass(x, 900)


def coin():
    d = 1.2
    x = np.zeros(int(d * SR))
    for k, (start, base) in enumerate([(0.0, 1180), (0.11, 1320)]):
        tt = t(1.0)
        s = sum(np.sin(2 * np.pi * base * r * tt) * a for r, a in [(1, 1), (2.4, 0.3), (3.9, 0.12)])
        s *= env(len(tt), 0.006, 0.35, curve=0.8)
        i = int(start * SR)
        x[i:i + len(s)] += s * (1 if k == 0 else 0.7)
    return lowpass(x, 2600)


def paper():
    d = 0.6
    n = band(noise(d), 300, 2600)
    flutter = 0.55 + 0.45 * np.abs(np.sin(2 * np.pi * 11 * t(d)))
    return n * flutter * env(len(n), 0.08, 0.3, hold=0.12)


def shutter():
    d = 1.2
    x = band(noise(d), 50, 450) * (0.7 + 0.3 * np.abs(np.sin(2 * np.pi * 9 * t(d))))
    x = x * env(len(x), 0.12, 0.6, hold=0.6)
    end = sine(lambda u: 70 - 20 * u, 0.5) * env(int(0.5 * SR), 0.01, 0.2)
    i = int(0.85 * SR)
    x[i:i + len(end)] += end[:len(x) - i] * 0.8
    return lowpass(x, 700)


def coinrain():
    d = 2.6
    x = np.zeros(int(d * SR))
    rng = np.random.default_rng(21)
    times = np.sort(rng.random(26) ** 1.6 * 2.0)
    for k, at in enumerate(times):
        base = rng.uniform(1000, 1500)
        tt = t(0.45)
        c = (np.sin(2 * np.pi * base * tt) + 0.3 * np.sin(2 * np.pi * base * 2.4 * tt)) * env(len(tt), 0.006, 0.12, curve=1.2)
        i = int(at * SR)
        x[i:i + len(c)] += c[:len(x) - i] * rng.uniform(0.35, 0.8)
    x += band(noise(d), 200, 1200) * env(int(d * SR), 0.3, 1.0, hold=1.2) * 0.12
    return lowpass(x, 2400)


def whirr():
    d = 2.4
    x = np.zeros(int(d * SR))
    at, gap, k = 0.0, 0.14, 0
    while at < 2.1:
        tk = band(noise(0.06), 500, 1500) * env(int(0.06 * SR), 0.009, 0.015)
        tk += sine(650 + 8 * k, 0.06) * env(int(0.06 * SR), 0.009, 0.02) * 0.4
        i = int(at * SR)
        x[i:i + len(tk)] += tk * (0.5 + 0.5 * min(1, at / 1.5))
        at += gap
        gap = max(0.035, gap * 0.9)
        k += 1
    fade = np.ones_like(x)
    fade[-int(0.3 * SR):] = np.linspace(1, 0, int(0.3 * SR))
    return lowpass(x * fade, 1900)


def flutter():
    d = 2.0
    x = np.zeros(int(d * SR))
    rng = np.random.default_rng(5)
    for at in np.sort(rng.random(9) * 1.5):
        f = band(noise(0.35), 300, 2400) * (0.55 + 0.45 * np.abs(np.sin(2 * np.pi * rng.uniform(9, 15) * t(0.35))))
        f *= env(len(f), 0.05, 0.15, hold=0.08)
        i = int(at * SR)
        x[i:i + len(f)] += f[:len(x) - i] * rng.uniform(0.5, 1.0)
    return x


def rise():
    d = 1.9
    tt = t(d)
    grow = (tt / d) ** 1.4
    x = band(noise(d), 60, 500) * grow
    x += sum(sine(f, d) * a for f, a in ((82.4, 0.5), (164.8, 0.35), (247.2, 0.2))) * grow
    fade = np.ones_like(x)
    fade[-int(0.35 * SR):] = np.linspace(1, 0, int(0.35 * SR)) ** 2
    return lowpass(x * fade * env(len(x), 0.4, d, hold=d), 900)


def melt():
    d = 1.8
    fr = lambda u: 440 * 2 ** (-1.2 * u / d)
    x = sum(sine(lambda u, m=m: m * fr(u), d) * a for m, a in ((1, 1), (2, 0.25), (1.5, 0.2)))
    return lowpass(x * env(int(d * SR), 0.08, 1.2, hold=0.4), 1600)


def sink():
    d = 2.8
    tt = t(d)
    body = band(noise(d), 80, 700) * np.exp(-tt * 0.6) * (0.6 + 0.4 * np.sin(np.pi * tt / d))
    x = body * 0.5
    rng = np.random.default_rng(31)
    for at in np.sort(rng.random(14) * 2.3):
        dur = rng.uniform(0.05, 0.1)
        bt = t(dur)
        f0 = rng.uniform(260, 520)
        chirp = np.sin(2 * np.pi * np.cumsum(f0 * (1 + 1.2 * bt / dur)) / SR) * np.sin(np.pi * bt / dur) ** 2
        i = int(at * SR)
        x[i:i + len(chirp)] += chirp[:len(x) - i] * rng.uniform(0.15, 0.35)
    return lowpass(x * env(len(x), 0.25, 1.4, hold=0.9), 1500)


def link():
    d = 0.5
    x = band(noise(d), 400, 1800) * env(int(d * SR), 0.014, 0.05)
    x += sine(lambda u: 180 + 60 * np.exp(-u * 30), d) * env(int(d * SR), 0.014, 0.12) * 0.6
    return lowpass(x, 1900)


def key():
    d = 0.9
    x = np.zeros(int(d * SR))
    rng = np.random.default_rng(41)
    for at, f0, amp in ((0.0, 1450, 1.0), (0.09, 1720, 0.7), (0.22, 1580, 0.45), (0.3, 1880, 0.3)):
        tt = t(0.5)
        c = (np.sin(2 * np.pi * f0 * tt) + 0.25 * np.sin(2 * np.pi * f0 * 2.3 * tt)) * env(len(tt), 0.008, 0.12, curve=1.0)
        i = int(at * SR)
        x[i:i + len(c)] += c[:len(x) - i] * amp * rng.uniform(0.9, 1.1)
    return lowpass(x, 2600)


def door():
    d = 1.6
    tt = t(d)
    air = band(noise(d), 120, 900) * np.sin(np.pi * np.clip(tt / 1.3, 0, 1)) ** 2
    knock = sine(lambda u: 90 + 40 * np.exp(-u * 20), 0.4) * env(int(0.4 * SR), 0.012, 0.12)
    x = air * 0.6
    x[:len(knock)] += knock * 0.5
    return lowpass(x * env(len(x), 0.02, 0.8, hold=0.8), 1200)


def vault():
    """A vault wheel turning (soft muted ticks slowing down), then a heavy, padded clunk and the door's air."""
    d = 2.2
    x = np.zeros(int(d * SR))
    at, gap, k = 0.0, 0.07, 0
    while at < 0.95:
        tk = band(noise(0.07), 300, 1100) * env(int(0.07 * SR), 0.01, 0.02)
        tk += sine(520 - 6 * k, 0.07) * env(int(0.07 * SR), 0.01, 0.025) * 0.35
        i = int(at * SR)
        x[i:i + len(tk)] += tk * 0.45
        at += gap
        gap *= 1.12
        k += 1
    i = int(1.05 * SR)
    clunk = sum(sine(lambda u, m=m: m * (48 + 40 * np.exp(-u * 22)), 0.9) * a for m, a in ((1, 1), (2, 0.5), (3, 0.2)))
    clunk *= env(len(clunk), 0.014, 0.35)
    clunk += band(noise(0.9), 90, 500) * env(int(0.9 * SR), 0.012, 0.08) * 0.4
    x[i:i + len(clunk)] += clunk[:len(x) - i]
    tt = t(d)
    x += band(noise(d), 100, 700) * np.clip((tt - 1.2) / 0.3, 0, 1) * np.exp(-np.clip(tt - 1.5, 0, None) * 2.2) * 0.25
    return lowpass(x, 1100)


def murmur():
    """A soft crowd murmur, voices without words: many low formant-like bursts that build and fade."""
    d = 3.2
    tt = t(d)
    x = np.zeros(len(tt))
    rng = np.random.default_rng(51)
    for _ in range(70):
        dur = rng.uniform(0.12, 0.35)
        f1 = rng.uniform(300, 700)
        b = band(noise(dur), f1 * 0.7, f1 * 1.5)
        b += sine(rng.uniform(110, 220), dur) * 0.25
        b *= np.sin(np.pi * t(dur) / dur) ** 2
        i = int(rng.random() * (d - dur) * SR)
        x[i:i + len(b)] += b * rng.uniform(0.3, 1.0)
    x += band(noise(d), 150, 900) * 0.25
    swell = np.sin(np.pi * np.clip(tt / d, 0, 1)) ** 0.8
    return lowpass(x * swell, 1300)


def aha():
    """Now I get it: two soft rising notes with a faint warm shimmer (the light bulb moment)."""
    d = 1.6
    x = np.zeros(int(d * SR))
    for at, f, a in ((0.0, 523.3, 0.8), (0.14, 784.0, 1.0)):
        tt = t(1.3)
        n = (np.sin(2 * np.pi * f * tt) + 0.2 * np.sin(2 * np.pi * f * 2 * tt)) * env(len(tt), 0.025, 0.5, curve=0.9)
        i = int(at * SR)
        x[i:i + len(n)] += n * a
    x += band(noise(d), 700, 1700) * env(int(d * SR), 0.2, 0.6, hold=0.2) * 0.06
    return lowpass(x, 1900)


def exhale():
    """Relief, now I can breathe again: a soft, warm breath out that settles."""
    d = 1.8
    tt = t(d)
    x = band(noise(d), 160, 900) * env(len(tt), 0.35, 0.9, hold=0.25)
    x += sine(lambda u: 220 - 30 * u / d, d) * env(len(tt), 0.4, 1.0, hold=0.3) * 0.18
    return lowpass(x, 1000)


def scribble():
    """Taking notes: a soft pencil on paper, a few short strokes."""
    d = 1.4
    x = np.zeros(int(d * SR))
    rng = np.random.default_rng(61)
    at = 0.0
    while at < 1.15:
        dur = rng.uniform(0.07, 0.16)
        s_ = band(noise(dur), 500, 1800) * np.sin(np.pi * t(dur) / dur) ** 1.5
        i = int(at * SR)
        x[i:i + len(s_)] += s_ * rng.uniform(0.5, 1.0)
        at += dur + rng.uniform(0.03, 0.09)
    return lowpass(x, 1900)


def laptop():
    """Let me get started: a soft hinge as a laptop opens, then a gentle two-note start-up."""
    d = 1.9
    x = band(noise(d), 120, 700) * env(int(d * SR), 0.15, 0.25, hold=0.25) * 0.5
    for at, f in ((0.62, 392.0), (0.78, 587.3)):
        tt = t(1.0)
        n = np.sin(2 * np.pi * f * tt) * env(len(tt), 0.03, 0.45, curve=0.9)
        i = int(at * SR)
        x[i:i + len(n)] += n[:len(x) - i] * 0.8
    return lowpass(x, 1600)


def ping():
    """A network waking up: three soft, round pings that ripple outward (computers lighting up around the world)."""
    d = 1.8
    x = np.zeros(int(d * SR))
    for at, f, a in ((0.0, 660.0, 1.0), (0.22, 784.0, 0.75), (0.44, 880.0, 0.55), (0.7, 988.0, 0.35)):
        tt = t(1.0)
        n = np.sin(2 * np.pi * f * tt) * env(len(tt), 0.02, 0.4, curve=1.0)
        i = int(at * SR)
        x[i:i + len(n)] += n[:len(x) - i] * a
    return lowpass(x, 1800)


def halve():
    """The reward halves: one soft note that steps down an octave, like a stair."""
    d = 0.9
    tt = t(d)
    step = np.where(tt < 0.16, 392.0, 196.0)
    ph = 2 * np.pi * np.cumsum(step) / SR
    x = (np.sin(ph) + 0.25 * np.sin(2 * ph)) * env(len(tt), 0.02, 0.45, hold=0.12, curve=0.9)
    return lowpass(x, 1400)


def engine():
    """A minibus taxi rolling past: a soft low hum that swells and fades, with a gentle wobble (no revving)."""
    d = 2.6
    tt = t(d)
    swell_ = np.sin(np.pi * np.clip(tt / d, 0, 1)) ** 1.3
    hum = sine(lambda u: 74 + 5 * np.sin(2 * np.pi * 3.1 * u), d) + 0.45 * sine(lambda u: 148 + 9 * np.sin(2 * np.pi * 3.1 * u), d)
    x = hum * 0.7 + band(noise(d), 60, 320) * (0.8 + 0.2 * np.sin(2 * np.pi * 7 * tt))
    return lowpass(x * swell_, 600)


def hoot():
    """A friendly double hoot, heard from far away: two short, round notes."""
    d = 0.75
    x = np.zeros(int(d * SR))
    for at in (0.0, 0.3):
        tt = t(0.24)
        n = (np.sin(2 * np.pi * 349.2 * tt) + 0.8 * np.sin(2 * np.pi * 440.0 * tt) + 0.2 * np.sin(2 * np.pi * 698.4 * tt)) * env(len(tt), 0.03, 0.09, hold=0.1, curve=1.2)
        i = int(at * SR)
        x[i:i + len(n)] += n
    return lowpass(x, 1300)


PALETTE = {
    'air': (air, 0.30), 'swell': (swell, 0.30), 'tension': (tension, 0.20), 'reveal': (reveal, 0.35),
    'drop': (drop, 0.15), 'glow': (glow, 0.35), 'chime': (chime, 0.30),
    'pluck1': (pluck(392.0), 0.25), 'pluck2': (pluck(440.0), 0.25), 'pluck3': (pluck(523.3), 0.25),
    'pluck4': (pluck(587.3), 0.25), 'pluck5': (pluck(659.3), 0.25),
    'tick': (tick, 0.12), 'count': (count, 0.12), 'clock': (clock, 0.12), 'thud': (thud, 0.15),
    'coin': (coin, 0.25), 'paper': (paper, 0.15), 'shutter': (shutter, 0.15),
    # made for video 01's 3D version
    'coinrain': (coinrain, 0.3), 'whirr': (whirr, 0.15), 'flutter': (flutter, 0.2), 'rise': (rise, 0.2), 'melt': (melt, 0.3),
    # made for video 02 (the stone money of Yap)
    'sink': (sink, 0.35), 'link': (link, 0.2),
    # made for video 03 (the 12 words)
    'key': (key, 0.3), 'door': (door, 0.3),
    # made for video 04 (myth or fact: is your money in a vault?)
    'vault': (vault, 0.3), 'murmur': (murmur, 0.25),
    # made for Leo's moments (10 November 2026): aha, relief, taking notes, getting started
    'aha': (aha, 0.35), 'exhale': (exhale, 0.3), 'scribble': (scribble, 0.15), 'laptop': (laptop, 0.25),
    # made for video 05 (how Bitcoin really works)
    'ping': (ping, 0.35), 'halve': (halve, 0.25),
    # made for video 06 (the hidden cost of your commute)
    'engine': (engine, 0.2), 'hoot': (hoot, 0.3),
}


def finish(x, wet):
    y = reverb(np.asarray(x, dtype=np.float64), wet=wet)
    mono = y.mean(axis=1)
    active = np.abs(mono) > 0.05 * np.abs(mono).max()
    rms = np.sqrt(np.mean(mono[active] ** 2))
    y *= 10 ** (TARGET_RMS_DB / 20) / rms
    peak = np.abs(y).max()
    limit = 10 ** (MAX_PEAK_DB / 20)
    if peak > limit:
        y *= limit / peak
    return y


def write_mp3(path, y):
    wav = path[:-4] + '.wav'
    with wave.open(wav, 'wb') as w:
        w.setnchannels(2)
        w.setsampwidth(2)
        w.setframerate(SR)
        w.writeframes((np.clip(y, -1, 1) * 32767).astype('<i2').tobytes())
    subprocess.run(['ffmpeg', '-v', 'error', '-y', '-i', wav, '-c:a', 'libmp3lame', '-b:a', '192k', path], check=True)
    os.remove(wav)


def measure(path):
    b = subprocess.run(['ffmpeg', '-v', 'error', '-i', path, '-ac', '1', '-ar', str(SR), '-f', 'f32le', '-'],
                       capture_output=True, check=True).stdout
    x = np.frombuffer(b, dtype=np.float32).astype(np.float64)
    spec = np.abs(np.fft.rfft(x * np.hanning(len(x)))) ** 2
    f = np.fft.rfftfreq(len(x), 1 / SR)
    centroid = float(np.sum(f * spec) / np.sum(spec))
    hf = float(np.sum(spec[f > 6000]) / np.sum(spec) * 100)
    k = int(0.002 * SR)
    sm = np.convolve(np.abs(x), np.ones(k) / k, 'same')
    p = sm.max()
    attack = (np.argmax(sm > 0.9 * p) - np.argmax(sm > 0.1 * p)) / SR * 1000
    peak = 20 * np.log10(np.abs(x).max())
    return centroid, hf, attack, peak


def cmd_check():
    files = sorted(glob.glob(os.path.join(SFX_DIR, '*.mp3')))
    bad = 0
    print(f"{'effect':9s} {'centroid':>9s} {'>6kHz':>6s} {'attack':>8s} {'peak':>7s}")
    for path in files:
        c, hf, a, pk = measure(path)
        problems = []
        if c > MAX_CENTROID_HZ:
            problems.append('too bright')
        if hf > MAX_HF_PERCENT:
            problems.append('hiss above 6 kHz')
        if a < MIN_ATTACK_MS:
            problems.append('click (attack too fast)')
        if pk > MAX_PEAK_DB + 0.5:
            problems.append('too loud')
        bad += bool(problems)
        print(f"{os.path.basename(path)[:-4]:9s} {c:7.0f}Hz {hf:5.1f}% {a:6.1f}ms {pk:5.1f}dB  {'OK' if not problems else ', '.join(problems)}")
    print(f'{len(files)} effects, {bad} too harsh' if bad else f'{len(files)} effects, all soft')
    return bad


def cmd_sfx():
    os.makedirs(SFX_DIR, exist_ok=True)
    for old in glob.glob(os.path.join(SFX_DIR, '*.mp3')):
        os.remove(old)  # the palette is replaced as a whole, so no harsh old effect survives
    for name, (fn, wet) in PALETTE.items():
        write_mp3(os.path.join(SFX_DIR, f'{name}.mp3'), finish(fn(), wet))
    print(f'{len(PALETTE)} effects -> {SFX_DIR}')
    return cmd_check()


ap = argparse.ArgumentParser()
ap.add_argument('what', choices=['sfx', 'check'])
a = ap.parse_args()
sys.exit(1 if (cmd_sfx() if a.what == 'sfx' else cmd_check()) else 0)
